 void edit(long id){page(false);editingScreen=true;editing=id;ContentValues r=new ContentValues();if(id>=0)for(ContentValues v:recipes())if(v.getAsLong("id")==id)r=v;photo=val(r,"photo");video=val(r,"video");body.addView(button("← Voltar",this::confirmLeave));space(body,25);body.addView(text(id<0?"Uma nova receita":"Editar receita",28,INK,true));space(body,22);name=field("Nome da receita",val(r,"name"),1,101);body.addView(text("Categoria",12,INK,true));categoryField=new Spinner(this);String[] cats={"Doces","Salgados","Pratos principais","Outros"};categoryField.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,cats));for(int i=0;i<cats.length;i++)if(cats[i].equals(val(r,"category")))categoryField.setSelection(i);body.addView(categoryField);space(body,18);time=field("Tempo de preparo",val(r,"time"),1,102);yield=field("Rendimento",val(r,"yield"),1,103);ingredients=field("Ingredientes · um por linha",val(r,"ingredients"),4,104);steps=field("Modo de preparo · um passo por linha",val(r,"steps"),5,105);photoLabel=button(photo.isEmpty()?"＋ Foto do prato pronto":"Trocar foto ✓",()->pick("image/*",41));body.addView(photoLabel);space(body,12);videoLabel=button(video.isEmpty()?"＋ Seu vídeo preparando":"Trocar vídeo ✓",()->pick("video/*",42));body.addView(videoLabel);space(body,20);notes=field("Dicas e memórias da vó",val(r,"notes"),3,106);body.addView(button("Guardar receita",this::save));}
 void pick(String mime,int request){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(mime);startActivityForResult(intent,request);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();Toast.makeText(this,"Guardando arquivo…",Toast.LENGTH_SHORT).show();new Thread(()->{File dir=new File(getFilesDir(),"media");dir.mkdirs();File dest=new File(dir,UUID.randomUUID().toString());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(dest)){if(in==null)throw new IOException();byte[] buffer=new byte[65536];long total=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>200L*1024*1024)throw new IOException("Escolha um arquivo de até 200 MB.");out.write(buffer,0,n);}runOnUiThread(()->{if(request==41){photo=dest.getAbsolutePath();if(photoLabel!=null)photoLabel.setText("Foto selecionada ✓");}else if(request==42){video=dest.getAbsolutePath();if(videoLabel!=null)videoLabel.setText("Vídeo selecionado ✓");}});}catch(Exception e){dest.delete();runOnUiThread(()->Toast.makeText(this,e.getMessage()==null?"Não foi possível importar o arquivo.":e.getMessage(),Toast.LENGTH_LONG).show());}}).start();}
 void save(){if(name.getText().toString().trim().isEmpty()||ingredients.getText().toString().trim().isEmpty()||steps.getText().toString().trim().isEmpty()){Toast.makeText(this,"Preencha nome, ingredientes e modo de preparo.",Toast.LENGTH_LONG).show();return;}ContentValues r=new ContentValues();r.put("name",name.getText().toString().trim());r.put("category",categoryField.getSelectedItem().toString());r.put("time",time.getText().toString());r.put("yield",yield.getText().toString());r.put("ingredients",ingredients.getText().toString());r.put("steps",steps.getText().toString());r.put("notes",notes.getText().toString());r.put("photo",photo);r.put("video",video);try{if(editing<0)db.insertOrThrow("recipes",null,r);else db.update("recipes",r,"id=?",new String[]{String.valueOf(editing)});Toast.makeText(this,"Receita guardada com carinho.",Toast.LENGTH_SHORT).show();home();}catch(Exception e){Toast.makeText(this,"Não foi possível salvar. Verifique o espaço do aparelho.",Toast.LENGTH_LONG).show();}}
 void confirmLeave(){new AlertDialog.Builder(this).setTitle("Sair sem salvar?").setMessage("As alterações desta receita serão descartadas.").setNegativeButton("Continuar editando",null).setPositiveButton("Sair",(a,b)->home()).show();}
